// STATEMENT INGEST — turning what a bank actually exports into the shapes everything else runs on.
//
// Every capability in this feature folds over `Txn` values and checks itself against
// `StatementPeriod` balances. Nothing produces those from a real CSV until this does, so this is
// where a wrong answer becomes possible in the most expensive way: silently, in the input.
//
// FOUR THINGS THAT LOOK LIKE PARSING AND ARE NOT:
//
//  1. THE SIGN. Institutions disagree, and they disagree in a way no assertion catches. Discover
//     writes a purchase as a POSITIVE number, because from their side you owing them more is an
//     increase. Bank of America writes the same purchase negative. Capital One does not use a signed
//     column at all — it uses two, Debit and Credit. Read one file with another's convention and
//     every total in this feature comes out backwards while looking entirely plausible.
//
//  2. THE DATE. `03/04/2026` is 4 March or 3 April and the file does not say which. When every date
//     in a file has both components under 13 the file is AMBIGUOUS, and there is no correct guess —
//     so this reports ambiguity rather than picking, and a profile must declare the format.
//
//  3. THE AMOUNT. `Math.round(parseFloat("8.115") * 100)` is 811, because 8.115 is really
//     8.11499999999999999. Amounts are parsed from the DECIMAL STRING, never multiplied through a
//     float, so the cent that goes missing here does not go missing in a reconcile later.
//
//  4. THE COMMAS. `AMAZON.COM, INC` is one quoted field. Splitting a CSV line on commas shifts every
//     column after it, so the amount is read out of the description and the row is rejected — or
//     worse, is not.
//
// AND THE PROFILES ARE NOT VERIFIED. They are written from documentation and memory, not from a real
// export of each institution. Every one carries `verified: false` and ingest says so loudly, because
// a plausible balance derived from a guessed column layout is exactly the failure this feature is
// built to prevent.
import { type Money, money } from "@/features/finance/lib/money";
import type { Txn } from "@/features/finance/lib/txn";
import type { StatementPeriod } from "@/features/finance/lib/reconcile";

export type DateFormat = "MM/DD/YYYY" | "DD/MM/YYYY" | "YYYY-MM-DD" | "MM/DD/YY";

/** One signed column. `outflowIsPositive` is the whole normalisation. */
export interface AmountSingle {
  readonly kind: "single";
  readonly column: string;
  /** True when the institution writes money LEAVING you as a positive number. */
  readonly outflowIsPositive: boolean;
}

/** Two columns, one of which is populated per row. */
export interface AmountSplit {
  readonly kind: "split";
  readonly debit: string;
  readonly credit: string;
}

export interface InstitutionProfile {
  readonly id: string;
  readonly institution: string;
  readonly dateColumn: string;
  readonly dateFormat: DateFormat;
  /** Joined with a space when an institution splits the description across columns. */
  readonly descriptionColumns: readonly string[];
  readonly amount: AmountSingle | AmountSplit;
  /** A running balance, where the export carries one — it is what lets `reconcile` run at all. */
  readonly balanceColumn?: string;
  /** FALSE until somebody has run a real export of this institution through it. */
  readonly verified: boolean;
  readonly caveat?: string;
}

export interface RejectedRow {
  /** 1-based line in the file, counting the header. */
  readonly line: number;
  readonly raw: readonly string[];
  readonly reason: string;
}

export interface IngestResult {
  readonly txns: readonly Txn[];
  /** Rows that could not be read. REPORTED, never dropped — a silently short file reconciles wrong. */
  readonly rejected: readonly RejectedRow[];
  /** Derived from the balance column when the export has one. */
  readonly period?: StatementPeriod;
  readonly warnings: readonly string[];
  readonly profile: string;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// CSV

/**
 * RFC-4180-shaped CSV: quoted fields, `""` for a literal quote, CRLF or LF, a BOM at the front.
 *
 * Written out rather than reached for because the alternative is splitting on commas, and merchant
 * names contain commas constantly.
 */
export function parseCsv(text: string): string[][] {
  const src = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let quoted = false;
  let started = false;

  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (quoted) {
      if (c === '"') {
        if (src[i + 1] === '"') {
          field += '"';
          i++;
        } else quoted = false;
      } else field += c;
      continue;
    }
    if (c === '"') {
      quoted = true;
      started = true;
      continue;
    }
    if (c === ",") {
      row.push(field);
      field = "";
      started = true;
      continue;
    }
    if (c === "\n" || c === "\r") {
      if (c === "\r" && src[i + 1] === "\n") i++;
      if (started || field.length) {
        row.push(field);
        rows.push(row);
      }
      row = [];
      field = "";
      started = false;
      continue;
    }
    field += c;
    started = true;
  }
  if (started || field.length) {
    row.push(field);
    rows.push(row);
  }
  return rows;
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Amounts

/**
 * An amount, from the DECIMAL STRING.
 *
 * `Math.round(parseFloat("8.115") * 100)` is 811. The binary double nearest 8.115 is slightly below
 * it, so the multiply lands at 811.4999999999999 and rounds down — one cent, in the input, before
 * anything has had a chance to check itself. Splitting the string at the point and rounding on the
 * first dropped digit cannot do that.
 *
 * Handles `$1,234.56`, `(1,234.56)` for accounting negatives, a leading sign, and a `DR`/`CR`
 * suffix, where DR is the raw positive and CR the raw negative — BEFORE a profile normalises them.
 */
export function parseAmount(raw: string, currency: string, units = 100): Money | undefined {
  let s = raw.trim();
  if (!s) return undefined;

  let negative = false;
  if (s.startsWith("(") && s.endsWith(")")) {
    negative = true;
    s = s.slice(1, -1);
  }
  s = s.replace(/[$£€¥\s,]/g, "");

  const suffix = /^(.*?)(CR|DR)$/i.exec(s);
  if (suffix) {
    s = suffix[1];
    if (suffix[2].toUpperCase() === "CR") negative = !negative;
  }
  if (s.startsWith("-")) {
    negative = !negative;
    s = s.slice(1);
  } else if (s.startsWith("+")) s = s.slice(1);

  if (!/^\d+(\.\d*)?$|^\.\d+$/.test(s)) return undefined;

  const dot = s.indexOf(".");
  const whole = dot === -1 ? s : s.slice(0, dot);
  const frac = dot === -1 ? "" : s.slice(dot + 1);
  const places = String(units).length - 1;
  const kept = (frac + "0".repeat(places)).slice(0, places);
  const dropped = frac.slice(places);

  let minor = Number(whole || "0") * units + Number(kept || "0");
  // Half-up on the first digit that does not fit. Rounding at all is a decision; doing it here, once,
  // in a place that says so, is the point of the exercise.
  if (dropped && Number(dropped[0]) >= 5) minor += 1;
  if (!Number.isSafeInteger(minor)) return undefined;

  return money(negative ? -minor : minor, currency);
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Dates

const DAYS_IN = (y: number, m: number): number => new Date(Date.UTC(y, m, 0)).getUTCDate();

/** ISO `YYYY-MM-DD`, or undefined when the text is not that date in that format. */
export function parseDate(raw: string, format: DateFormat): string | undefined {
  const s = raw.trim();
  let y: number, m: number, d: number;

  if (format === "YYYY-MM-DD") {
    const hit = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(s);
    if (!hit) return undefined;
    [y, m, d] = [Number(hit[1]), Number(hit[2]), Number(hit[3])];
  } else {
    const hit = /^(\d{1,2})[/-](\d{1,2})[/-](\d{2}|\d{4})$/.exec(s);
    if (!hit) return undefined;
    const [a, b] = [Number(hit[1]), Number(hit[2])];
    y = Number(hit[3]);
    if (hit[3].length === 2) y += y >= 70 ? 1900 : 2000;
    [m, d] = format === "DD/MM/YYYY" ? [b, a] : [a, b];
  }
  if (m < 1 || m > 12 || d < 1 || d > DAYS_IN(y, m)) return undefined;
  return `${String(y).padStart(4, "0")}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
}

export type FormatVerdict = "MM/DD/YYYY" | "DD/MM/YYYY" | "ambiguous" | "contradictory" | "unknown";

/**
 * What a column of dates CAN be, which is not always one thing.
 *
 * A file whose every date has both components under 13 is genuinely ambiguous — `03/04` is 4 March
 * or 3 April and nothing in the file decides it. Guessing is a one-in-two chance of shifting every
 * transaction by weeks, so this says `ambiguous` and the profile has to declare.
 */
export function detectDateFormat(samples: readonly string[]): FormatVerdict {
  let dayFirst = false;
  let monthFirst = false;
  let sawSlash = false;
  for (const s of samples) {
    const hit = /^(\d{1,2})[/-](\d{1,2})[/-](\d{2}|\d{4})$/.exec(s.trim());
    if (!hit) continue;
    sawSlash = true;
    if (Number(hit[1]) > 12) dayFirst = true;
    if (Number(hit[2]) > 12) monthFirst = true;
  }
  if (dayFirst && monthFirst) return "contradictory";
  if (dayFirst) return "DD/MM/YYYY";
  if (monthFirst) return "MM/DD/YYYY";
  return sawSlash ? "ambiguous" : "unknown";
}

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Profiles

/**
 * The four institutions asked for. EVERY ONE IS UNVERIFIED — written from documentation, not from a
 * real export — and the `caveat` on each says exactly what to check first. Running a real file
 * through and flipping `verified` is a deliberate act, which is the point.
 */
export const INSTITUTION_PROFILES: readonly InstitutionProfile[] = [
  {
    id: "discover",
    institution: "Discover",
    dateColumn: "Trans. Date",
    dateFormat: "MM/DD/YYYY",
    descriptionColumns: ["Description"],
    // A PURCHASE IS POSITIVE. From the issuer's side, you owing more is an increase.
    amount: { kind: "single", column: "Amount", outflowIsPositive: true },
    verified: false,
    caveat: "check the sign on a PURCHASE row first — if a purchase comes out positive after ingest, outflowIsPositive is wrong",
  },
  {
    id: "capital-one",
    institution: "Capital One",
    dateColumn: "Transaction Date",
    dateFormat: "YYYY-MM-DD",
    descriptionColumns: ["Description"],
    // Two columns, one populated per row. No sign to get wrong, which is why it is the easy one.
    amount: { kind: "split", debit: "Debit", credit: "Credit" },
    verified: false,
    caveat: "confirm the header spelling and whether the export uses ISO dates or MM/DD/YYYY",
  },
  {
    id: "bank-of-america",
    institution: "Bank of America",
    dateColumn: "Date",
    dateFormat: "MM/DD/YYYY",
    descriptionColumns: ["Description"],
    amount: { kind: "single", column: "Amount", outflowIsPositive: false },
    balanceColumn: "Running Bal.",
    verified: false,
    caveat: "the export begins with a summary block ABOVE the header row; strip everything before the header line before ingest",
  },
  {
    id: "chase",
    institution: "Chase",
    dateColumn: "Posting Date",
    dateFormat: "MM/DD/YYYY",
    descriptionColumns: ["Description"],
    amount: { kind: "single", column: "Amount", outflowIsPositive: false },
    balanceColumn: "Balance",
    verified: false,
    caveat: "the credit-card export and the chequing export are DIFFERENT layouts — the card one has Transaction Date and no Balance",
  },
];

export const profileFor = (id: string): InstitutionProfile | undefined =>
  INSTITUTION_PROFILES.find((p) => p.id === id);

// ─────────────────────────────────────────────────────────────────────────────────────────────────
// Ingest

const norm = (s: string): string => s.trim().toLowerCase().replace(/\s+/g, " ");

/**
 * OUTFLOWS OUTNUMBER INFLOWS on any real account, and by a lot — dozens of purchases against one or
 * two deposits, dozens of charges against one payment. So a file that comes out the other way round
 * is the loudest available evidence that the sign convention is inverted. It cannot prove it, so it
 * warns rather than refuses; a month of nothing but refunds is unusual, not impossible.
 */
export function signLooksInverted(txns: readonly Txn[], ratio = 2): boolean {
  const out = txns.filter((t) => t.amount.minor < 0).length;
  const inn = txns.filter((t) => t.amount.minor > 0).length;
  return txns.length >= 10 && inn > out * ratio;
}

export function ingest(
  text: string,
  profile: InstitutionProfile,
  account: string,
  currency: string,
): IngestResult {
  const warnings: string[] = [];
  const rows = parseCsv(text);
  if (!rows.length) {
    return { txns: [], rejected: [], warnings: ["the file is empty"], profile: profile.id };
  }

  const header = rows[0].map(norm);
  const at = (name: string): number => header.indexOf(norm(name));

  const required = [
    profile.dateColumn,
    ...profile.descriptionColumns,
    ...(profile.amount.kind === "single" ? [profile.amount.column] : [profile.amount.debit, profile.amount.credit]),
  ];
  const missing = required.filter((c) => at(c) === -1);
  if (missing.length) {
    // REFUSE THE WHOLE FILE. A missing column is not a bad row — it means the profile does not
    // describe this export, and reading it row by row would produce a confident, wrong list.
    return {
      txns: [],
      rejected: [],
      warnings: [
        `this file does not match the ${profile.institution} profile: no column named ${missing.join(", ")}. Found: ${rows[0].join(", ")}`,
      ],
      profile: profile.id,
    };
  }

  if (!profile.verified) {
    warnings.push(
      `the ${profile.institution} profile is NOT verified against a real export${profile.caveat ? ` — ${profile.caveat}` : ""}. Check a handful of rows against the statement before trusting a balance.`,
    );
  }

  const dateAt = at(profile.dateColumn);
  const verdict = detectDateFormat(rows.slice(1).map((r) => r[dateAt] ?? ""));
  if (verdict === "ambiguous") {
    warnings.push(
      `every date in this file has both components under 13, so the file cannot say whether it is MM/DD or DD/MM — the ${profile.dateFormat} in the profile is being TAKEN ON TRUST, and if it is wrong every transaction moves by weeks`,
    );
  } else if (verdict === "contradictory") {
    warnings.push("the date column contains both DD/MM and MM/DD rows — something upstream has already mixed two exports");
  } else if (verdict !== "unknown" && verdict !== profile.dateFormat) {
    warnings.push(`the dates in this file look like ${verdict}, but the profile says ${profile.dateFormat}`);
  }

  const txns: Txn[] = [];
  const rejected: RejectedRow[] = [];
  const balances: { date: string; balance: Money; amount: Money }[] = [];
  const balanceAt = profile.balanceColumn ? at(profile.balanceColumn) : -1;

  for (let i = 1; i < rows.length; i++) {
    const raw = rows[i];
    if (raw.every((c) => !c.trim())) continue;
    const reject = (reason: string): void => void rejected.push({ line: i + 1, raw, reason });

    const date = parseDate(raw[dateAt] ?? "", profile.dateFormat);
    if (!date) {
      reject(`'${raw[dateAt] ?? ""}' is not a ${profile.dateFormat} date`);
      continue;
    }

    const description = profile.descriptionColumns
      .map((c) => (raw[at(c)] ?? "").trim())
      .filter(Boolean)
      .join(" ");
    if (!description) {
      reject("no description");
      continue;
    }

    let amount: Money | undefined;
    if (profile.amount.kind === "single") {
      const parsed = parseAmount(raw[at(profile.amount.column)] ?? "", currency);
      if (!parsed) {
        reject(`'${raw[at(profile.amount.column)] ?? ""}' is not an amount`);
        continue;
      }
      // THE NORMALISATION, in one place: negative is money leaving the account holder.
      amount = profile.amount.outflowIsPositive ? money(-parsed.minor, currency) : parsed;
    } else {
      const debit = parseAmount(raw[at(profile.amount.debit)] ?? "", currency);
      const credit = parseAmount(raw[at(profile.amount.credit)] ?? "", currency);
      if (debit && credit) {
        reject("both the debit and the credit column are populated");
        continue;
      }
      if (!debit && !credit) {
        reject("neither the debit nor the credit column is populated");
        continue;
      }
      amount = debit ? money(-Math.abs(debit.minor), currency) : money(Math.abs(credit!.minor), currency);
    }

    txns.push({ date, description, amount, account });
    if (balanceAt !== -1) {
      const balance = parseAmount(raw[balanceAt] ?? "", currency);
      if (balance) balances.push({ date, balance, amount });
    }
  }

  if (signLooksInverted(txns)) {
    warnings.push(
      "more money comes IN than goes OUT across these rows, which almost never happens on a real account — check the sign convention on this profile before trusting anything derived from it",
    );
  }
  if (rejected.length) {
    warnings.push(`${rejected.length} row(s) could not be read and are listed rather than dropped — a silently short file reconciles wrong`);
  }

  return {
    txns,
    rejected,
    ...(balances.length ? { period: periodFrom(balances, account, currency) } : {}),
    warnings,
    profile: profile.id,
  };
}

/**
 * The statement window and its two balances, from a running-balance column.
 *
 * The opening balance is the FIRST row's running balance MINUS that row's own amount — the running
 * balance is stated after the transaction, so taking it as the opening double-counts the first row.
 */
function periodFrom(
  balances: readonly { date: string; balance: Money; amount: Money }[],
  account: string,
  currency: string,
): StatementPeriod {
  const sorted = [...balances].sort((a, b) => a.date.localeCompare(b.date));
  const first = sorted[0];
  const last = sorted[sorted.length - 1];
  return {
    account,
    from: first.date,
    to: last.date,
    opening: money(first.balance.minor - first.amount.minor, currency),
    closing: last.balance,
  };
}

/** Ingest several files into one list — the ordinary case, since accounts export separately. */
export function ingestAll(
  files: readonly { readonly text: string; readonly profile: InstitutionProfile; readonly account: string }[],
  currency: string,
): { txns: Txn[]; periods: StatementPeriod[]; rejected: RejectedRow[]; warnings: string[] } {
  const txns: Txn[] = [];
  const periods: StatementPeriod[] = [];
  const rejected: RejectedRow[] = [];
  const warnings: string[] = [];
  for (const f of files) {
    const r = ingest(f.text, f.profile, f.account, currency);
    txns.push(...r.txns);
    if (r.period) periods.push(r.period);
    rejected.push(...r.rejected);
    warnings.push(...r.warnings.map((w) => `${f.account}: ${w}`));
  }
  return {
    txns: txns.sort((a, b) => a.date.localeCompare(b.date)),
    periods,
    rejected,
    warnings,
  };
}

