import { describe, it, expect } from "vitest";
import { fromMajor } from "@/features/finance/lib/money";
import { reconcile } from "@/features/finance/lib/reconcile";
import {
  INSTITUTION_PROFILES,
  type InstitutionProfile,
  detectDateFormat,
  ingest,
  ingestAll,
  parseAmount,
  parseCsv,
  parseDate,
  profileFor,
  signLooksInverted,
} from "@/features/finance/lib/ingest";

// SYNTHETIC FIXTURES ONLY. Every CSV below is invented — no real statement, balance or account
// number belongs in this repo, and none of these are real exports.
const usd = (major: number) => fromMajor(major, "USD");

describe("parseCsv — a merchant name with a comma in it", () => {
  it("keeps a quoted comma inside its field", () => {
    // Splitting on commas shifts every column after this one, so the amount is read out of the
    // description. It is the single most common way a CSV importer is quietly wrong.
    const rows = parseCsv('Date,Description,Amount\n01/02/2026,"AMAZON.COM, INC",-42.10\n');
    expect(rows[1]).toEqual(["01/02/2026", "AMAZON.COM, INC", "-42.10"]);
  });

  it("un-escapes a doubled quote", () => {
    expect(parseCsv('a,b\n1,"JOE""S DINER"\n')[1]).toEqual(["1", 'JOE"S DINER']);
  });

  it("handles CRLF, a BOM and a missing final newline", () => {
    const rows = parseCsv('﻿Date,Amount\r\n01/02/2026,-1.00\r\n01/03/2026,-2.00');
    expect(rows[0]).toEqual(["Date", "Amount"]);
    expect(rows).toHaveLength(3);
    expect(rows[2]).toEqual(["01/03/2026", "-2.00"]);
  });

  it("keeps an empty trailing field rather than losing the column", () => {
    expect(parseCsv("a,b,c\n1,,3\n")[1]).toEqual(["1", "", "3"]);
    expect(parseCsv("a,b,c\n1,2,\n")[1]).toEqual(["1", "2", ""]);
  });

  it("keeps a newline inside a quoted field", () => {
    expect(parseCsv('a,b\n1,"two\nlines"\n')[1]).toEqual(["1", "two\nlines"]);
  });
});

describe("parseAmount — from the decimal STRING, never through a float", () => {
  it("rounds the half up, where a float multiply rounds it down", () => {
    // The binary double nearest 1.005 is slightly BELOW it, so 1.005 * 100 is 100.49999999999999 and
    // Math.round gives 100. One cent, in the input, before anything can check itself.
    //
    // These four are MEASURED, not chosen for effect — the first guess for this test was 8.115,
    // which happens to land ABOVE and rounds correctly. Which values misbehave is not something to
    // reason about from the outside, and that is the argument for not going through a float at all.
    for (const [text, viaFloat, correct] of [
      ["0.145", 14, 15],
      ["0.285", 28, 29],
      ["1.005", 100, 101],
      ["1.035", 103, 104],
    ] as const) {
      expect(Math.round(parseFloat(text) * 100)).toBe(viaFloat);
      expect(parseAmount(text, "USD")!.minor).toBe(correct);
    }
  });

  it("reads the ordinary shapes", () => {
    expect(parseAmount("1234.56", "USD")!.minor).toBe(123456);
    expect(parseAmount("$1,234.56", "USD")!.minor).toBe(123456);
    expect(parseAmount("-42.10", "USD")!.minor).toBe(-4210);
    expect(parseAmount("+42.10", "USD")!.minor).toBe(4210);
    expect(parseAmount("42", "USD")!.minor).toBe(4200);
    expect(parseAmount(".50", "USD")!.minor).toBe(50);
    expect(parseAmount("0.00", "USD")!.minor).toBe(0);
  });

  it("reads an accounting negative in brackets", () => {
    expect(parseAmount("(1,234.56)", "USD")!.minor).toBe(-123456);
    expect(parseAmount("($42.10)", "USD")!.minor).toBe(-4210);
  });

  it("reads a DR/CR suffix as the RAW convention, before any profile normalises it", () => {
    expect(parseAmount("42.10 DR", "USD")!.minor).toBe(4210);
    expect(parseAmount("42.10 CR", "USD")!.minor).toBe(-4210);
  });

  it("returns undefined rather than a plausible zero for what is not an amount", () => {
    // A zero here would balance a statement that does not balance.
    for (const bad of ["", "  ", "n/a", "--", "1.2.3", "12x", "$"]) {
      expect(parseAmount(bad, "USD")).toBeUndefined();
    }
  });
});

describe("parseDate and detectDateFormat — 03/04 is not one date", () => {
  it("reads each declared format", () => {
    expect(parseDate("03/04/2026", "MM/DD/YYYY")).toBe("2026-03-04");
    expect(parseDate("03/04/2026", "DD/MM/YYYY")).toBe("2026-04-03");
    expect(parseDate("2026-03-04", "YYYY-MM-DD")).toBe("2026-03-04");
    expect(parseDate("3/4/26", "MM/DD/YY")).toBe("2026-03-04");
  });

  it("rejects a date that does not exist", () => {
    expect(parseDate("02/30/2026", "MM/DD/YYYY")).toBeUndefined();
    expect(parseDate("13/01/2026", "MM/DD/YYYY")).toBeUndefined();
    expect(parseDate("02/29/2026", "MM/DD/YYYY")).toBeUndefined();
    expect(parseDate("02/29/2024", "MM/DD/YYYY")).toBe("2024-02-29");
  });

  it("says AMBIGUOUS when nothing in the file decides it", () => {
    // Every component under 13. Guessing is a one-in-two chance of moving every transaction by weeks.
    expect(detectDateFormat(["03/04/2026", "05/06/2026", "01/02/2026"])).toBe("ambiguous");
  });

  it("resolves as soon as one row cannot be the other way round", () => {
    expect(detectDateFormat(["03/04/2026", "25/06/2026"])).toBe("DD/MM/YYYY");
    expect(detectDateFormat(["03/04/2026", "06/25/2026"])).toBe("MM/DD/YYYY");
  });

  it("calls a file that contains both CONTRADICTORY rather than picking a winner", () => {
    expect(detectDateFormat(["25/06/2026", "06/25/2026"])).toBe("contradictory");
  });

  it("says unknown when there is nothing slash-shaped to judge", () => {
    expect(detectDateFormat(["2026-03-04", ""])).toBe("unknown");
  });
});

describe("ingest — THE SIGN, normalised in one place", () => {
  const discover = profileFor("discover")!;
  const boa = profileFor("bank-of-america")!;

  it("negates a Discover purchase, which the file writes as POSITIVE", () => {
    // From the issuer's side, you owing more is an increase. Read with the other convention, every
    // total in this feature comes out backwards while looking entirely plausible.
    const csv = 'Trans. Date,Post Date,Description,Amount,Category\n06/03/2026,06/04/2026,"SAFEWAY #221",84.10,Groceries\n06/05/2026,06/06/2026,"PAYMENT - THANK YOU",-300.00,Payments\n';
    const r = ingest(csv, discover, "card", "USD");
    expect(r.txns).toHaveLength(2);
    expect(r.txns[0].amount.minor).toBe(usd(-84.1).minor);
    expect(r.txns[1].amount.minor).toBe(usd(300).minor);
  });

  it("leaves a Bank of America amount alone, which is already signed our way", () => {
    const csv = 'Date,Description,Amount,Running Bal.\n06/03/2026,"SAFEWAY #221",-84.10,"1,915.90"\n';
    const r = ingest(csv, boa, "checking", "USD");
    expect(r.txns[0].amount.minor).toBe(usd(-84.1).minor);
  });

  it("reads a Capital One split debit/credit pair with no sign to get wrong", () => {
    const cap = profileFor("capital-one")!;
    const csv = "Transaction Date,Posted Date,Description,Debit,Credit\n2026-06-03,2026-06-04,SAFEWAY,84.10,\n2026-06-05,2026-06-06,PAYMENT,,300.00\n";
    const r = ingest(csv, cap, "card", "USD");
    expect(r.txns[0].amount.minor).toBe(usd(-84.1).minor);
    expect(r.txns[1].amount.minor).toBe(usd(300).minor);
  });

  it("rejects a split row that is populated on both sides, or on neither", () => {
    const cap = profileFor("capital-one")!;
    const csv = "Transaction Date,Description,Debit,Credit\n2026-06-03,BOTH,10.00,10.00\n2026-06-04,NEITHER,,\n";
    const r = ingest(csv, cap, "card", "USD");
    expect(r.txns).toHaveLength(0);
    expect(r.rejected.map((x) => x.reason)).toEqual([
      "both the debit and the credit column are populated",
      "neither the debit nor the credit column is populated",
    ]);
  });

  it("warns when more money comes IN than goes out, which almost never happens", () => {
    const rows = Array.from({ length: 12 }, (_, i) => `06/${String(i + 1).padStart(2, "0")}/2026,06/04/2026,"CHARGE ${i}",50.00,X`).join("\n");
    // Read with the WRONG convention: a file of purchases comes out as a file of deposits.
    const wrong: InstitutionProfile = { ...discover, amount: { kind: "single", column: "Amount", outflowIsPositive: false } };
    const r = ingest(`Trans. Date,Post Date,Description,Amount,Category\n${rows}\n`, wrong, "card", "USD");
    expect(r.warnings.join(" ")).toContain("almost never happens");
    expect(signLooksInverted(r.txns)).toBe(true);
  });

  it("does not cry inversion on a small handful of rows", () => {
    expect(signLooksInverted([{ date: "2026-06-01", description: "X", amount: usd(10), account: "a" }])).toBe(false);
  });
});

describe("ingest — what it refuses, and what it merely reports", () => {
  const boa = profileFor("bank-of-america")!;

  it("REFUSES the whole file when a column the profile needs is absent", () => {
    // A missing column is not a bad row — it means the profile does not describe this export, and
    // reading it row by row would produce a confident, wrong list.
    const r = ingest("Posted,Memo,Value\n06/03/2026,X,1.00\n", boa, "checking", "USD");
    expect(r.txns).toEqual([]);
    expect(r.rejected).toEqual([]);
    expect(r.warnings.join(" ")).toContain("does not match the Bank of America profile");
    expect(r.warnings.join(" ")).toContain("Posted, Memo, Value");
  });

  it("reports a bad row with its line number rather than dropping it", () => {
    const csv = 'Date,Description,Amount,Running Bal.\n06/03/2026,"OK",-10.00,100.00\n06/32/2026,"BAD DATE",-10.00,90.00\n06/05/2026,"BAD AMOUNT",n/a,80.00\n06/06/2026,"",-10.00,70.00\n';
    const r = ingest(csv, boa, "checking", "USD");
    expect(r.txns).toHaveLength(1);
    expect(r.rejected.map((x) => x.line)).toEqual([3, 4, 5]);
    expect(r.rejected[0].reason).toContain("not a MM/DD/YYYY date");
    expect(r.rejected[1].reason).toContain("not an amount");
    expect(r.rejected[2].reason).toBe("no description");
    expect(r.warnings.join(" ")).toContain("silently short file reconciles wrong");
  });

  it("says every packaged profile is UNVERIFIED, because none of them is", () => {
    expect(INSTITUTION_PROFILES.every((p) => p.verified === false)).toBe(true);
    expect(INSTITUTION_PROFILES.every((p) => (p.caveat ?? "").length > 0)).toBe(true);
    const r = ingest('Date,Description,Amount,Running Bal.\n06/03/2026,"X",-10.00,100.00\n', boa, "checking", "USD");
    expect(r.warnings.join(" ")).toContain("NOT verified against a real export");
    expect(r.warnings.join(" ")).toContain("summary block ABOVE the header row");
  });

  it("takes a declared date format on trust and SAYS it is doing so", () => {
    const csv = 'Date,Description,Amount,Running Bal.\n03/04/2026,"X",-10.00,100.00\n05/06/2026,"Y",-10.00,90.00\n';
    const r = ingest(csv, boa, "checking", "USD");
    expect(r.warnings.join(" ")).toContain("TAKEN ON TRUST");
    expect(r.txns[0].date).toBe("2026-03-04");
  });

  it("says when the file's dates disagree with the profile", () => {
    const csv = 'Date,Description,Amount,Running Bal.\n25/06/2026,"X",-10.00,100.00\n';
    const r = ingest(csv, boa, "checking", "USD");
    expect(r.warnings.join(" ")).toContain("look like DD/MM/YYYY");
    // And the row itself is rejected, because 25 is not a month.
    expect(r.rejected).toHaveLength(1);
  });

  it("has nothing to say about an empty file except that it is empty", () => {
    expect(ingest("", boa, "checking", "USD").warnings).toEqual(["the file is empty"]);
  });
});

describe("ingest — the running balance is what lets reconcile run at all", () => {
  const boa = profileFor("bank-of-america")!;
  const csv =
    'Date,Description,Amount,Running Bal.\n' +
    '06/03/2026,"OPENING SPEND",-100.00,"900.00"\n' +
    '06/10/2026,"PAY",1000.00,"1,900.00"\n' +
    '06/20/2026,"RENT",-1500.00,"400.00"\n';

  it("derives the opening balance by BACKING OUT the first row's own amount", () => {
    // The running balance is stated AFTER the transaction. Taking it as the opening double-counts
    // the first row, and the statement then fails to reconcile by exactly that amount.
    const r = ingest(csv, boa, "checking", "USD");
    expect(r.period!.opening.minor).toBe(usd(1000).minor);
    expect(r.period!.closing.minor).toBe(usd(400).minor);
    expect(r.period!.from).toBe("2026-06-03");
    expect(r.period!.to).toBe("2026-06-20");
  });

  it("produces a period that actually RECONCILES against its own transactions", () => {
    // The end-to-end claim: a file goes in, and what comes out passes the gate everything else is
    // behind. If the sign, the amounts or the opening balance were wrong, this would not balance.
    const r = ingest(csv, boa, "checking", "USD");
    const rec = reconcile(r.txns, [r.period!]);
    expect(rec.problems).toEqual([]);
    expect(rec.ok).toBe(true);
    expect(rec.ledger).toBeDefined();
    expect(rec.ledger!.through).toBe("2026-06-20");
  });

  it("has no period at all when the export carries no balance column", () => {
    const discover = profileFor("discover")!;
    const r = ingest('Trans. Date,Description,Amount\n06/03/2026,"X",10.00\n', discover, "card", "USD");
    expect(r.period).toBeUndefined();
  });
});

